sys_ux_data_broker_transform.required_translations:
[ {
  "message" : "Json with payload after technician's selections",
  "comment" : ""
}, {
  "message" : "Request ID",
  "comment" : ""
}, {
  "message" : "Updated Data",
  "comment" : ""
} ]

sys_ux_data_broker_transform.script:
function transform (input) {

	gs.info("Transform started");
	for (var sysId in input.updatedData) {
		var data = input.updatedData[sysId];
		gs.info("Processing sys_id: " + sysId + ", Data: " + JSON.stringify(data));

		var gr = new GlideRecord('x_1120851_ottrack_ot_request_line');
		if (gr.get(sysId)) {

			if (data.hasOwnProperty('selected')) {
				gr.setValue('selected', data.selected);
			}
			if (data.hasOwnProperty('skip')) {
				gr.setValue('skip', data.skip);
			}

			if (data.hasOwnProperty('skip_reason')) {
				gr.setValue('skip_reason', data.skip_reason[0]);
			}
			gr.update();
		}
	}
	var req = new GlideRecord('x_1120851_ottrack_ot_request'); 
	req.get(input.reqestId);
	req.setValue('request_state', 'Requested');

}
